enderer.EmoteCount==hostSpeech+1&&guestRenderer.EmoteCount==guestSpeech,"Duplicate snapshot never replays optional hero speech");
  g.Players[0].Mana=10;PublishLan();BeginPower();PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.CardId=="VAN_EX1_tk34"),"Inferno summons through normal skill button");Check(g.Players[0].Mana==8&&g.Players[0].PowerUsed&&guest.match.Players[0].Board.Single().Health==6&&guest.match.Players[0].Hand.Count==0,"Inferno cost usage body and private hand agree");UseWeaponSlot(0,true);ClickMatchTarget(new MatchTarget(1));PumpLan(()=>guest.match.Players[1].Health==27,"Blood Fury attacks through weapon slot");Check(g.Players[0].WeaponDurability==7,"Weapon attack consumes one durability");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest turn starts");
